n = int(input())

def nprf(n):
    pf = {}
    for i in range(2, n+1):
        for j in range(2, i+1):
            while i % j == 0:
                if not j in pf:
                    pf[j] = 0
                pf[j] += 1
                i //= j
    return pf

pf = nprf(n)

def f(n):
    count = 0
    for v in pf.values():
        if v >= n-1:
            count += 1
    return count

f1 = f(75)
f2 = f(25) * (f(3)-1)
f3 = f(15) * (f(5)-1)
f4 = f(5) * (f(5)-1) //2 * (f(3)-2)

print(f1 + f2 + f3 + f4)

